    log.debug("- saveAppointment");
    Calendar start = Calendar.getInstance();
    start.setTimeInMillis(start.getTimeInMillis() + 600000);
    Calendar end = Calendar.getInstance();
    end.setTimeInMillis(start.getTimeInMillis() + 600000);
