@Test
public void reportTest() {
    // null report
    Response resp = getClient(getErrorUrl()).path("/report").post("");
    assertNotNull(resp, "Not null Response should be returned");
    assertEquals(Response.Status.NO_CONTENT.getStatusCode(), resp.getStatus(), "SUCCESS result should be returned");
    // report with message
    resp = getClient(getErrorUrl()).path("/report").query("message", "Dummy test").post("");
    assertNotNull(resp, "Not null Response should be returned");
    assertEquals(Response.Status.NO_CONTENT.getStatusCode(), resp.getStatus(), "SUCCESS result should be returned");
    // report with invalid sid and message
    resp = getClient(getErrorUrl()).path("/report").query("message", "Dummy test").query("sid", "n/a").post("");
    assertNotNull(resp, "Not null Response should be returned");
    assertEquals(Response.Status.NO_CONTENT.getStatusCode(), resp.getStatus(), "SUCCESS result should be returned");
    // report with valid sid and no message
    ServiceResult r = login();
    resp = getClient(getErrorUrl()).path("/report").query("sid", r.getMessage()).post("");
    assertNotNull(resp, "Not null Response should be returned");
    assertEquals(Response.Status.NO_CONTENT.getStatusCode(), resp.getStatus(), "SUCCESS result should be returned");
    // report with valid sid and message
    resp = getClient(getErrorUrl()).path("/report").query("sid", r.getMessage()).query("message", "Dummy test").post("");
    assertNotNull(resp, "Not null Response should be returned");
    assertEquals(Response.Status.NO_CONTENT.getStatusCode(), resp.getStatus(), "SUCCESS result should be returned");
}

@Test
@Tag("org.apache.openmeetings.test.NonJenkinsTests")
public void addFileTest() throws IOException {
    File img = null;
    try {
        img = File.createTempFile("omtest", ".jpg");
        final Integer width = 150;
        final Integer height = 100;
        BufferedImage image = new BufferedImage(width, height, BufferedImage.TYPE_INT_RGB);
        Graphics g = image.getGraphics();
        g.drawString("Hello World!!!", 10, 20);
        ImageIO.write(image, "jpg", img);
        CallResult<FileItemDTO> cr = createVerifiedFile(img, "test.txt", BaseFileItem.Type.Presentation);
        assertEquals(BaseFileItem.Type.Image, cr.getObj().getType(), "Type should be Image");
        assertEquals(width, cr.getObj().getWidth(), "Width should be determined");
        assertEquals(height, cr.getObj().getHeight(), "Height should be Image");
    } finally {
        if (img != null && img.exists()) {
            img.delete();
        }
    }
}

